impl api::v1::OpenOptions {
    /// Unset `auto_sync` means off. Index is always `{vault}/.scheda/index`.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    #[must_use]
    pub fn auto_sync(self, auto_sync: bool) -> Self {
        self.with_auto_sync(auto_sync)
    }

    /// Clone URL when `open` path does not exist. Unset means local `git init`.
    /// A set value must be an absolute URI (`https://…`, `ssh://…`, `file:///…`).
    #[must_use]
    pub fn remote_repo(self, remote_repo: impl Into<String>) -> Self {
        self.with_remote_repo(remote_repo)
    }

    /// Age secret for this handle. Unset: encryption is not requested.
    /// When set, `passphrase` or `identity` is required. Applies to
    /// encryption generally, not only to `{vault}/.isolated/`.
    ///
    /// A build without the `encrypt` crate feature refuses a set value
    /// (`unsupported_encryption`) before any directory is created.
    /// With that feature, `open` stores the secret on the handle for
    /// I/O of collections whose declaration marks `encrypted`.
    #[must_use]
    pub fn encryption(mut self, encryption: api::v1::Encryption) -> Self {
        self.encryption = ::buffa::MessageField::some(encryption);
        self
    }

    /// Git author and committer. Unset: local git config, then
    /// `Scheda <scheda@invalid>`.
    #[must_use]
    pub fn author(mut self, author: api::v1::Author) -> Self {
        self.author = ::buffa::MessageField::some(author);
        self
    }

    /// Machine-local identity of the process that writes this clone.
    /// Unset: generated on first `open` and stored in `{vault}/.scheda/writer`.
    #[must_use]
    pub fn writer(self, writer: impl Into<String>) -> Self {
        self.with_writer(writer)
    }

    /// Fail if this message does not satisfy `api/v1` field rules.
    pub fn require_valid(&self) -> Result<(), api::v1::Error> {
        require_valid(self)
    }
}

