#[cfg(test)]
mod tests {
    use protovalidate_buffa::Validate;

    use super::api::v1::{
        Author, ColumnKind, Declaration, Encryption, Error, Filter, FindQuery, IndexColumn,
        IndexSchema, Journal, OpenOptions, Record, SearchQuery, Unit, history,
    };

    #[test]
    fn error_json_uses_lib5_code_string() {
        let err = Error::default()
            .with_code(super::api::v1::error::Code::NotFound)
            .with_message("missing id")
            .with_repeat(super::api::v1::error::Repeat::Forbidden);
        let json = serde_json::to_value(&err).expect("json");
        assert_eq!(json["code"], "CODE_NOT_FOUND");
        assert_eq!(json["message"], "missing id");
    }

    #[test]
    fn open_options_json_uses_protobuf_json_names() {
        let opts = OpenOptions::default().with_auto_sync(false);
        let json = serde_json::to_value(&opts).expect("json");
        assert_eq!(json["autoSync"], false);
        assert!(json.get("write").is_none());
        assert!(json.get("indexDir").is_none());
        assert!(json.get("remoteRepo").is_none());
        let cloned = OpenOptions::new().remote_repo("file:///tmp/scheda.git");
        let json = serde_json::to_value(&cloned).expect("json");
        assert_eq!(json["remoteRepo"], "file:///tmp/scheda.git");
        let named = OpenOptions::new().author(Author::new().name("Ada").email("ada@invalid"));
        let json = serde_json::to_value(&named).expect("json");
        assert_eq!(json["author"]["name"], "Ada");
        assert_eq!(json["author"]["email"], "ada@invalid");
        let encrypted =
            OpenOptions::new().encryption(Encryption::new().passphrase("test-passphrase"));
        let json = serde_json::to_value(&encrypted).expect("json");
        assert_eq!(json["encryption"]["passphrase"], "test-passphrase");
        assert!(json["encryption"].get("identity").is_none());
        assert!(json.get("encrypt").is_none());
        assert!(json.get("secret").is_none());
    }

    #[test]
    fn open_options_author_requires_name_and_email() {
        assert!(
            OpenOptions::new()
                .author(Author::new().name("Ada"))
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .author(Author::new().email("ada@invalid"))
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .author(Author::new().name("Ada").email("ada@invalid"))
                .validate()
                .is_ok()
        );
        assert!(
            OpenOptions::new()
                .author(Author::new().name("Ada<").email("ada@invalid"))
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .author(Author::new().name("Ada").email("ada invalid"))
                .validate()
                .is_err()
        );
    }

    #[test]
    fn open_options_remote_repo_must_be_uri() {
        assert!(OpenOptions::new().validate().is_ok());
        assert!(
            OpenOptions::new()
                .remote_repo("file:///tmp/scheda.git")
                .validate()
                .is_ok()
        );
        assert!(
            OpenOptions::new()
                .remote_repo("https://example.test/repo.git")
                .validate()
                .is_ok()
        );
        assert!(OpenOptions::new().remote_repo("").validate().is_err());
        assert!(
            OpenOptions::new()
                .remote_repo("/tmp/repo")
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .remote_repo("git@host:repo.git")
                .validate()
                .is_err()
        );
    }

    #[test]
    fn open_options_writer_token() {
        assert!(OpenOptions::new().writer("alice").validate().is_ok());
        assert!(OpenOptions::new().writer("host-1").validate().is_ok());
        assert!(OpenOptions::new().writer("a").validate().is_ok());
        assert!(OpenOptions::new().writer("").validate().is_err());
        assert!(OpenOptions::new().writer("Alice").validate().is_err());
        assert!(OpenOptions::new().writer("a_b").validate().is_err());
        assert!(OpenOptions::new().writer("-abc").validate().is_err());
        assert!(OpenOptions::new().writer("00000001").validate().is_ok());
    }

    #[test]
    fn open_options_encryption_requires_secret() {
        assert!(OpenOptions::new().validate().is_ok());
        assert!(
            OpenOptions::new()
                .encryption(Encryption::new())
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .encryption(Encryption::new().passphrase("test-passphrase"))
                .validate()
                .is_ok()
        );
        assert!(
            OpenOptions::new()
                .encryption(Encryption::new().identity("AGE-SECRET-KEY-TEST"))
                .validate()
                .is_ok()
        );
        assert!(
            OpenOptions::new()
                .encryption(Encryption::new().passphrase(""))
                .validate()
                .is_err()
        );
        assert!(
            OpenOptions::new()
                .encryption(Encryption::new().identity(""))
                .validate()
                .is_err()
        );
        assert!(Encryption::new().validate().is_err());
        assert!(
            Encryption::new()
                .passphrase("test-passphrase")
                .require_valid()
                .is_ok()
        );
    }

    #[test]
    fn record_raw_is_base64_bytes() {
        let record = Record::default()
            .with_id("alpha")
            .with_raw(b"hello".to_vec());
        let json = serde_json::to_value(&record).expect("json");
        assert_eq!(json["id"], "alpha");
        assert!(json.get("collection").is_none());
        assert!(json.get("fields").is_none());
        assert!(json.get("body").is_none());
        assert!(json.get("valid").is_none());
        assert_eq!(json["raw"], "aGVsbG8=");
    }

    #[test]
    fn error_code_is_required() {
        assert!(Error::default().validate().is_err());
        assert!(Error::not_found("missing").validate().is_ok());
    }

    #[test]
    fn open_options_default_is_valid() {
        assert!(OpenOptions::default().validate().is_ok());
        assert!(OpenOptions::new().require_valid().is_ok());
    }

    #[test]
    fn empty_filter_is_invalid_all_is_valid() {
        assert!(Filter::default().validate().is_err());
        assert!(Filter::all().validate().is_ok());
        assert!(Filter::all().require_valid().is_ok());
    }

    #[test]
    fn find_query_filter_is_required() {
        assert!(FindQuery::default().validate().is_err());
        assert!(FindQuery::all().require_valid().is_ok());
        assert!(FindQuery::from(Filter::all()).require_valid().is_ok());
    }

    #[test]
    fn record_default_is_valid() {
        assert!(Record::default().validate().is_ok());
        assert!(Record::default().require_valid().is_ok());
        assert!(Record::default().with_id("alpha").require_valid().is_ok());
    }

    #[test]
    fn history_entry_time_json_is_rfc3339() {
        let json = serde_json::to_value(history::Entry::default().with_time(0)).expect("json");
        assert_eq!(json["time"], "1970-01-01T00:00:00Z");
    }

    #[test]
    fn search_query_text_is_required() {
        assert!(SearchQuery::default().validate().is_err());
        assert!(
            SearchQuery::default()
                .with_text("token")
                .require_valid()
                .is_ok()
        );
        let err = SearchQuery::default()
            .require_valid()
            .expect_err("missing text");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
    }

    #[test]
    fn search_query_weights_are_finite_and_non_negative() {
        let ok = SearchQuery::default().with_text("token");
        assert!(ok.require_valid().is_ok());
        assert!(
            ok.clone()
                .with_lexical_weight(0.0)
                .with_vector_weight(0.0)
                .require_valid()
                .is_ok()
        );
        let err = ok
            .clone()
            .with_lexical_weight(-1.0)
            .require_valid()
            .expect_err("negative lexical_weight");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
        let err = ok
            .clone()
            .with_vector_weight(f64::NAN)
            .require_valid()
            .expect_err("NaN vector_weight");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
        let err = ok
            .clone()
            .with_lexical_weight(f64::INFINITY)
            .require_valid()
            .expect_err("+Inf lexical_weight");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
        let err = ok
            .with_vector_weight(f64::NEG_INFINITY)
            .require_valid()
            .expect_err("-Inf vector_weight");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
    }

    #[test]
    fn search_query_rerank_limit_rejects_zero() {
        let ok = SearchQuery::default().with_text("token");
        assert!(ok.clone().with_rerank_limit(1).require_valid().is_ok());
        let err = ok
            .with_rerank_limit(0)
            .require_valid()
            .expect_err("zero rerank_limit");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
    }

    #[test]
    fn search_hit_has_no_field_validators() {
        let hit = super::api::v1::search_hits::Hit::default().with_id("alpha");
        assert!(hit.validate().is_ok());
        assert!(hit.clone().with_rrf_score(-0.1).validate().is_ok());
        assert!(hit.with_lexical_score(f64::NAN).validate().is_ok());
    }

    #[test]
    fn kind_is_required() {
        assert!(Declaration::default().validate().is_err());
        let err = Declaration::default()
            .require_valid()
            .expect_err("missing kind");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));
        let ok = Declaration {
            kind: Unit::default().into(),
            ..Declaration::default()
        };
        assert!(ok.require_valid().is_ok());
        let json = serde_json::to_value(&ok).expect("json");
        assert!(json.get("version").is_none());
        assert!(json.get("document").is_some());
        assert!(json.get("fields").is_none());
    }

    #[test]
    fn journal_may_exclude_either_index_leg() {
        for (lexical, vector) in [(true, false), (false, true), (true, true)] {
            let decl = Declaration {
                kind: Journal::default().into(),
                ..Declaration::default()
            }
            .with_exclude_lexical_index(lexical)
            .with_exclude_vector_index(vector);
            assert!(
                decl.require_valid().is_ok(),
                "journal lexical={lexical} vector={vector}"
            );
        }
    }

    #[test]
    fn index_schema_column_rules() {
        assert!(IndexSchema::default().require_valid().is_ok());
        let ok = IndexSchema {
            columns: vec![
                IndexColumn::default()
                    .with_name("title")
                    .with_kind(ColumnKind::Text)
                    .with_find(true),
            ],
            ..IndexSchema::default()
        };
        assert!(ok.require_valid().is_ok());

        let dup = IndexSchema {
            columns: vec![
                IndexColumn::default()
                    .with_name("title")
                    .with_kind(ColumnKind::Text),
                IndexColumn::default()
                    .with_name("title")
                    .with_kind(ColumnKind::Integer),
            ],
            ..IndexSchema::default()
        };
        let err = dup.require_valid().expect_err("duplicate names");
        assert_eq!(err.known_code(), Some(super::api::v1::error::Code::Invalid));

        let reserved = IndexSchema {
            columns: vec![
                IndexColumn::default()
                    .with_name("id")
                    .with_kind(ColumnKind::Text),
            ],
            ..IndexSchema::default()
        };
        assert!(reserved.require_valid().is_err());

        let missing_kind = IndexSchema {
            columns: vec![IndexColumn::default().with_name("title")],
            ..IndexSchema::default()
        };
        assert!(missing_kind.require_valid().is_err());

        let unspecified = IndexSchema {
            columns: vec![
                IndexColumn::default()
                    .with_name("title")
                    .with_kind(ColumnKind::Unspecified),
            ],
            ..IndexSchema::default()
        };
        assert!(unspecified.require_valid().is_err());
    }
}
